-- RetroCameraLand - Retro Club acilis hesaplari (100 uye: No. 0001-0100). schema_club_v3.sql'den SONRA, BIR KEZ calistir.
-- Bu hesaplar is_seed = true ile isaretlidir ve kartlari 'void' oldugu icin kimse bu hesaplara giris yapamaz.
-- Hepsini kaldirmak icin:  delete from club_members where is_seed;  delete from club_cards where batch = 'seed';
do $$
begin
  if exists (select 1 from club_members where is_seed) then
    raise notice 'Acilis hesaplari zaten ekli; atlandi.';
    return;
  end if;
  -- Varsa onceki (gercek/test) uyeleri 101'den itibaren yeniden numarala; 1-100 acilis hesaplarina ayrilir.
  update club_members set member_no = -member_no;
  update club_members m set member_no = 100 + r.rn
    from (select id, row_number() over (order by joined_at, id) as rn from club_members) r where r.id = m.id;



  -- Bundan sonraki uyelikler 101'den (ya da en buyuk numaradan) devam eder.
  perform setval('club_member_no_seq', greatest(100, (select max(member_no) from club_members), (select coalesce(max(member_no), 0) from club_cards)));
end $$;
